"""Build the current English research site and readable GitHub notes. Standard library only."""
from pathlib import Path
from html import escape
import json

ROOT=Path(__file__).resolve().parent
def load(name):return json.loads((ROOT/'data'/name).read_text(encoding='utf-8'))
SOURCES=load('sources.json')
QUOTES=load('speculation-quotes.json')
FIGURES=load('figure-credits.json')
def e(s):return escape(str(s),quote=True)
def cite(*nums):return ' '.join(f'<a class="citation" href="#ref-{n}" aria-label="Reference {n}">[{n}]</a>' for n in nums)
def paras(items):return ''.join('<p>'+x+'</p>' for x in items)
def ext(url,label):return f'<a href="{e(url)}" target="_blank" rel="noopener noreferrer">{label}<span class="sr-only"> (opens in a new tab)</span> ↗</a>'

BOOK_IMAGES=load('book-case-images.json')
def book_case_figure(case):
    figures=[]
    for file in case.get('images',[]):
        item=next(x for x in BOOK_IMAGES if x['file']==file)
        png=(ROOT/'assets/book-cases'/file).read_bytes()
        width,height=int.from_bytes(png[16:20],'big'),int.from_bytes(png[20:24],'big')
        figures.append(f'<figure class="book-case-figure"><a href="assets/book-cases/{e(file)}" target="_blank" rel="noopener"><img src="assets/book-cases/{e(file)}" width="{width}" height="{height}" loading="lazy" alt="Book figure screenshot: {e(item["title"])}. Printed page {item["printed_page"]}. Click to enlarge."></a><figcaption>{e(item["title"])}. <i>Speculative Everything</i>, printed p. {item["printed_page"]}. {e(item["credit"])} {cite(21)} <span>Figure and original caption cropped from the supplied book. Click to enlarge.</span></figcaption></figure>')
    return '<div class="book-case-images">'+''.join(figures)+'</div>'

VERSION=load('design-version.json')
TIMELINE=load('iteration.json')

COPY=load('comparison-copy.json')
HEADERS=COPY['headers']
import re
def inline_refs(s):return re.sub(r'\[(\d+)\]',lambda m:cite(int(m.group(1))),s)
ROWS=[[inline_refs(c) for c in row] for row in COPY['rows']]
SPECULATION_CASES=load('speculation-case-analysis.json')
for row,case in zip(ROWS,SPECULATION_CASES):
    row[3]=(f'<b>The book case.</b> <i>{case["case"]}</i>{book_case_figure(case)}<p>{case["description"]}</p>'
      f'<p><b>The idea we borrow.</b> {case["lesson"]}</p>'
      f'<p><b>How it connects to this probe.</b> {case["relation"]}</p>'
      f'<p><b>The step it changes.</b> {case["change"]}</p>'
      f'<p><b>How this helps us choose.</b> {case["selection"]}</p>'
      f'<p><b>The authors’ words.</b></p><q>{e(case["quote"])}</q><p>Dunne & Raby, printed pp. {case["pages"]}. {cite(21)} '
      f'<a href="#excerpt-{case["passage"]}">Read the quotation and case →</a></p>')

DIRECTIONS=load('probe-designs.json')

def preview(d):
    labels=['Approve a photo','See AI’s preview','Fold or reposition','Compare the next response'] if d['id']=='a' else ['Express a meaning','AI assists','Receive a reply','Clarify and keep a card']
    return '<div class="live-sketch"><span class="eyebrow">WORKING PROBE CONCEPT</span><div class="sketch-flow">'+'<b>→</b>'.join('<span>'+x+'</span>' for x in labels)+'</div><p>Round 1 explores this direction through low-fidelity prototypes.</p><a href="#round1-'+d['id']+'">See its Round 1 version →</a></div>'



def extra_detail(d):
    import re
    text=(ROOT/'content'/('probe-'+d['id']+'.html')).read_text(encoding='utf-8')
    return re.sub(r'\[(\d+)\]',lambda m:cite(int(m.group(1))),text)

def heading(num,title,desc=''):
    return f'<div class="section-heading"><span class="eyebrow">{num}</span><h2>{title}</h2>'+ ('<p class="section-intro">'+desc+'</p>' if desc else '')+'</div>'

def direction(d):
    theory=''.join(f'<h4>{t}</h4><p>{s} {cite(*r)}</p>' for t,s,r in d['theory'])
    return f'''<article class="direction direction-{d['id']}" id="probe-{d['id']}"><div class="direction-head"><div><span class="route-label">PROBE {d['letter']} · {e(d['origin'])}</span><h3>{d['title']}</h3><p class="direction-summary">{d['sentence']}</p><div class="chips"><span>{d['focus']}</span><span>Working concept under development</span></div></div><span class="direction-letter" aria-hidden="true">{d['letter']}</span></div>
    <div class="direction-opening"><div><h4>The research question</h4><p class="research-question">{d['rq']}</p><p>{d['purpose']}</p><h4>AI’s intended role</h4><p>{d['ai']}</p></div><div>{preview(d)}</div></div><h4 class="subsection-title">The intended interaction</h4><ol class="workflow">{''.join('<li><b>'+t+'</b><p>'+x+'</p></li>' for t,x in d['steps'])}</ol>{extra_detail(d)}
    <div class="detail-grid"><details><summary>Theory, HCI and possible contribution</summary>{theory}<h4>What the research could contribute</h4><p>{d['value']} {cite(*d['refs'])}</p></details><details><summary>Evidence to develop across iterations</summary><p>{d['record']}</p><p>{d['analysis']}</p><p>{d['checkpoint']}</p><a href="#round1-data">Read the separate Round 1 data plan →</a></details></div>
    <details><summary>Set-up and participation in the working concept</summary><p>{d['setup']}</p><p>{d['broad']}</p><p>{d['noai']}</p></details>
    <details class="speculative-use"><summary>Where speculation enters this probe concept</summary><p>{d['future']}</p><p>{d['speculation']}</p><p>Book support: {', '.join('<a href="#excerpt-'+str(n)+'">Passage '+str(n)+'</a>' for n in d['quotenums'])}. {cite(21)}</p><p>The book-based future scenario explains the concept. Round 1 follows the submitted activities and questionnaire below.</p></details></article>'''

def figure(i,alt):
    f=FIGURES[i]
    png=(ROOT/'assets/research'/f['file']).read_bytes()
    width,height=int.from_bytes(png[16:20],'big'),int.from_bytes(png[20:24],'big')
    return f'''<figure class="paper-figure"><a href="assets/research/{f['file']}" target="_blank" rel="noopener"><img src="assets/research/{f['file']}" alt="{e(alt)}" width="{width}" height="{height}"></a><figcaption>{e(f['authors'])} ({f['year']}), original Figure {f['figure']}. {ext(f['doi'],'Paper')} · {ext(f['source_pdf'],'Author PDF')} · {ext(f['license_url'],f['license'])}. Cropped to the figure, with its content unchanged.</figcaption></figure>'''

comparison='<div class="comparison-wrap" tabindex="0" role="region" aria-label="Five-probe comparison table"><table><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in HEADERS)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td data-label="{e(h)}">{c}</td>' for h,c in zip(HEADERS,row))+'</tr>' for row in ROWS)+'</tbody></table></div>'

hero='''<section class="hero" id="overview"><div class="hero-copy"><span class="eyebrow">TWO PROBE CONCEPTS · ITERATIVE DEVELOPMENT</span><h1>Two directions.<br>One first prototype round.</h1><p class="hero-lead">A explores authenticity through material interaction with AI. B explores cross-cultural understanding through AI-mediated exchange.</p><p>Five starting ideas led to these two working concepts. We now explore both through Round 1 low-fidelity prototypes, learn from the feedback and develop the next iteration before selecting a direction.</p><div class="hero-actions"><a class="button" href="#directions">Understand A &amp; B ↓</a><a class="text-link" href="#evaluation">See Round 1 →</a></div><p class="status-line"><span class="status-dot"></span>Concepts under development · Round 1 protocol: ERGO 117392 V1.0, 22 October 2026</p></div><aside class="reading-guide"><span class="eyebrow">READ THE PAGE IN THREE STEPS</span><a href="#directions"><span class="mini-letter a">1</span><div><b>The two probe concepts</b><p>What each interaction aims to explore.</p></div><span>↗</span></a><a href="#evaluation"><span class="mini-letter b">2</span><div><b>Round 1 prototypes</b><p>How the first low-fidelity round explores them.</p></div><span>↗</span></a><a href="#comparison"><span class="mini-letter a">3</span><div><b>Why five became two</b><p>Feedback, book cases and research behind the choice.</p></div><span>↗</span></a></aside></section><div class="development-path" aria-label="Development path"><span>Five initial ideas</span><b>→</b><span>Two probe concepts</span><b>→</b><span>Round 1 · low fidelity</span><b>→</b><span>Refine, iterate and select</span></div>'''

research='<p class="scope-note">A and B have separate research questions. The cuff, bag and postcard are interaction forms for exploring those questions. Their first prototypes are part of an ongoing design process.</p>'

iteration=f'''<section id="iteration">{heading('03 / DEVELOPMENT AND SELECTION','Why five became two, and what happens next','Meeting and interview feedback shaped the two concepts. The ethics protocol specifies their first low-fidelity round.')}<div class="timeline">{''.join('<article><span>'+n+'</span><h3>'+title+'</h3><p>'+text+'</p></article>' for n,title,text in TIMELINE)}</div><div class="selection-note"><h3>The selection criterion: make participation broad</h3><p>Consider language, heritage knowledge, material skill, arriving alone, personal devices and the option to decline AI. These guide the working concepts. Round 1 begins with adult ECS staff and students and uses the submitted participation choices.</p><p>Develop 2 as A. Combine 4 and 5 as B. Keep 1 as an introductory idea and pause 3 as a standalone probe. Feedback from prototype rounds will support further refinement and eventual selection.</p></div></section>'''

evidence=f'''<section id="evidence">{heading('05 / RESEARCH AND REAL PRACTICE','How research informs these activities','Follow the study, the observation and the design choice it helps us make.')}
<article class="evidence-case" id="huayao-case"><div class="case-heading"><span>01 / MAKING</span><h3>Huayao embroidery: follow a change and its reason</h3></div>{figure(0,'Huayao embroiderers, selected and discarded generated images, finished embroidery and creative goals')}<div class="evidence-reasoning"><h4>The original study</h4><p>Eight experienced Huayao embroiderers worked through a six-month, four-stage process. It included 152 embroidery images, three generation workflows, selecting images and making embroidery. The final in-situ stages lasted eight days. Researchers used interviews during making, a focus group and open coding. The publication is a CHI 2026 extended abstract. {cite(12)}</p><h4 id="huayao-findings">What the researchers observed</h4><p>Participants selected, discarded and changed generated images. Their reasons included familiar local motifs, animal forms, line density and what would work in embroidery. The authors describe how making helped bring further judgments into view.</p><p class="paper-quote">Dianhua: “I still have to change it a bit”. The authors’ discussion: “many of the modifications made during the making offer insights”. {cite(12)}</p><h4 id="huayao-to-a">The step this changes in A</h4><p>Connect the source, example and participant’s written reason clearly. In the A concept, follow the source, physical adjustment, AI response and the person’s reason together. Round 1 begins with material arrangement and prepared effects. Its questionnaire and optional caption help refine how to explore authenticity. Experienced embroidery and a brief visitor activity offer different settings for this way of examining making.</p><p>The study informs our attention to reasons that develop through practice. A’s visitor task investigates how those reasons relate a named work to a personal item. <a href="#a-authenticity">See the authenticity guide</a> and <a href="#a-art-morph">the Art Morph comparison</a>. {cite(1,2,12)}</p></div></article>
<article class="evidence-case"><div class="case-heading"><span>02 / SOCIAL RELATIONSHIPS</span><h3>The AI Pattern Merchant: place a working design in a social setting</h3></div><div class="figure-pair">{figure(1,'The AI Pattern Merchant with a prompting board, sample display and portable printer')}{figure(2,'Generated pattern samples among existing embroidery patterns at a stall')}</div><div class="two-col"><div><h4>What happened</h4><p>The project brought prompting, generation and printing into a Huayao festival and the relationships of making and exchange. The authors report attention to the inserted samples and record that none were purchased. {cite(11)}</p></div><div><h4>The design lesson</h4><p>A working object gives people something concrete to encounter and discuss. A’s intended previews and B’s conversation-linked postcard make a wider museum arrangement imaginable. Round 1 begins with prepared examples and a local whiteboard.</p></div></div></article>
<article class="evidence-case"><div class="case-heading"><span>03 / LANGUAGE</span><h3>Let people clarify in their own language</h3></div>{figure(3,'Three machine-translation interfaces with quality labels and two forms of post-editing')}<div class="two-col"><div><h4>What the study found</h4><p>A study of 45 dyads of Chinese new immigrants and English-speaking residents in the US examined translation interfaces. Post-editing supported greater exercise of agency and added costs to the conversation. {cite(9)}</p></div><div><h4>The step this changes in B</h4><p>B’s concept uses AI language assistance while preserving original words and real replies. Round 1 explores the conversation and its related postcard through original-language messages, prepared images and labelled multilingual starter notes. Participant text stays outside AI services in this round.</p></div></div><p>Research on cultural detail in AI writing and colour-name translation also helps us look closely at what a fluent version carries. {cite(8,10)}</p></article>
<h3 class="subsection-title">Useful museum and HCI precedents</h3><div class="practice-grid"><article><h4>Cleveland Museum of Art</h4><p>Art Morph connects materials with generated art. Endless Threads combines a camera cutout with a chosen textile using OpenCV. These offer two forms for linking a person with a collection image. {cite(22,29)}</p></article><article><h4>GIFT and personal records</h4><p>GIFT connects objects with personal messages. Museum data souvenirs connect a visit with a personal take-away. B develops that take-away inside the conversation. {cite(15,16,26)}</p></article><article><h4>Embodied generation</h4><p>Body-prompting research and A(I)Cam show ways to make generation an embodied public or reflective experience. A borrows the idea of material exploration. Its Round 1 prototypes use prepared everyday-item effects and written reflections. {cite(30,31)}</p></article></div>
<details><summary>Other research and reading scope</summary><p>AI co-writing informs the distinction between a writer’s approval and a reader’s understanding. Heritage narratives, TwistLens and Gen-Diaolou add context for interpretation and transformation. Nasher provides an AI curatorial-text precedent. {cite(3,4,5,14,25)}</p><p>ZOMA is used through its abstract as a hybrid-craft precedent. The empathy paper is also used at abstract level as a prompt to consider attribution. Source entries identify the material read and the study setting. {cite(7,20)}</p></details></section>'''

speculation=f'''<section id="speculation">{heading('06 / SPECULATIVE DESIGN REASONING','The original words and the ideas they give us','The book cases explain the working concepts and their imagined museum arrangements. Round 1 has its own limited procedure and questions.')}<div class="two-col"><div><h3>A possible future for A</h3><p>A museum shares adaptations for everyday cuffs and bags. A small postcard can help people imagine how a source pattern enters personal life.</p></div><div><h3>A possible future for B</h3><p>A museum shows visitor interpretations together with the replies that shaped them. A postcard wall makes questions about visibility and voice concrete.</p></div></div><p><b>How this informs the two concepts.</b> Use clear source-to-example links in A and keep original words with the chosen image in B. The concepts use these props to open discussion about museum interpretation. Round 1 explores their initial forms through the submitted activities and questionnaire. Further iterations can develop the speculative encounter.</p><p class="small">Thirteen original passages from Anthony Dunne and Fiona Raby’s <i>Speculative Everything</i> (2013) are preserved below with printed page numbers. Interpretations and design applications are ours. Book figures keep their original captions and credits. {cite(21)}</p><button type="button" id="quote-toggle" class="quiet-button">Open all original passages</button><div class="quote-list">{''.join(f'<details class="quote" id="excerpt-{q["number"]}"><summary><span>Passage {q["number"]} · pp. {q["pages"]}</span>{q["title"]}</summary>{book_case_figure(SPECULATION_CASES[q["number"]-9]) if q["number"]>=9 else ""}<p>{e(q.get("creator",""))}{". " if q.get("creator") else ""}{e(q.get("case_description",""))}</p><blockquote>{e(q["original"])}</blockquote><p class="quote-source">Dunne &amp; Raby (2013), Chapter {q["chapter"]}, pp. {q["pages"]}. {cite(21)}</p><h4>The idea we take from it</h4><p>{q["meaning"]}</p><h4>How it informs the design</h4><p>{q["application"]}</p></details>' for q in QUOTES)}</div></section>'''

objects='''<section id="objects">'''+heading('07 / DIGITAL OBJECT REFERENCES','Keep a named source and its context visible','The Round 1 protocol uses images and collection information for 1–2 objects from the two target venues.')+'''<div class="object-layout"><figure class="venue-photo"><img src="https://godshousetower.org.uk/wp-content/uploads/LS-Everyone-Involved-launch-9-scaled.jpg" alt="Historical installation view of Ian Giles’s Everyone Involved from God’s House Tower’s official record" loading="lazy" referrerpolicy="no-referrer"><figcaption>Historical exhibition image from the venue website. Artwork: Ian Giles. Rights remain with the rights holders.</figcaption></figure><div><h3>A textile candidate for the examples</h3><p>Ian Giles’s <i>Everyone Involved</i>, shown at God’s House Tower in 2024, includes found and vintage textile wall hangings. The venue states that the work would enter Southampton City Art Gallery’s collection. Select the exact permitted image and checked contextual information before preparing study examples. '''+cite(28)+'''</p><h3>Tudor House &amp; Garden</h3><p>Use a confirmed source image and its collection information. The Leather Jug is a leather collection highlight. A textile-focused selection needs a confirmed textile reference. Preserve the actual maker, exhibition and collection source for every image. '''+cite(27)+'''</p></div></div><p>Digital references let participants consider the same object. Language and cultural perspective remain open to the participant’s own expression. The <a href="#evaluation">Round 1 prototypes</a> takes place in ECS. The target venues inform later museum development.</p></section>'''

sources='<section id="sources">'+heading('08 / REFERENCES','Sources and reading scope','Numeric references are used throughout. Formal papers, extended abstracts, theory books and official practice records have different evidential roles.')+'<p>Main literature search cut-off: 14 October 2026. Targeted checks for material interaction, Art Morph and the revised A were added on 16 October. Original quotations and figures were checked on 16 October. This is a focused synthesis for design decisions. ZOMA and the empathy study are used at abstract level. The Huayao extended abstract is labelled as such. Sources inform the design choices. Round 1 feedback will help refine the two concepts and inform further iterations.</p><ol class="sources">'+''.join(f'<li id="ref-{r["number"]}" value="{r["number"]}">{e(r["title"])} {ext(r["url"],"Source")}<p class="small">{e(r.get("reading_scope",""))}</p></li>' for r in SOURCES)+'</ol><p class="small">Paper figures retain their individual Creative Commons licences, credited below each image. The book quotations and figure screenshots support discussion of the specific cases. Each figure keeps its original caption and credit. Rights remain with the named rights holders. No open licence is claimed for the book figures. No full papers, book chapters, raw interview records, camera data, private drafts or API credentials are included.</p></section>'

